#!/usr/local/bin/prhm-node
'use strict';
const fs=require('node:fs');
const path=require('node:path');
const crypto=require('node:crypto');
const cp=require('node:child_process');

const ACTION='honartik_staging_privilege_boundary_install_v1';
const OPERATION='host_action.honartik_staging_privilege_boundary_install_v1';
const POLICY_VERSION='2026-09-21.1-honartik-staging-privilege-boundary-v1';
const ROLLBACK='host-action-v2:honartik-staging-privilege-boundary-install-v1:file-rollback';

const BASE_SHA='6ae89522f439babd3b6a9679336aea0fb12bb74993d33234095f872d38ad8cc6';
const EXEC_SHA='409b63bd48b3363eaec2b3921f77ece2767dff93f6143923bdb754fe8f4cf69c';
const POLICY_SHA='9672e88b8c5033b7107e921d25bd4911216e86a8fe593ee67ac2330e0a75bab2';
const MCP_SHA='703a8f8ee0726fac47d008a69c759e3f52254c980cf551ea3f2660cc46321283';

const DRIVER_SHA='a711ab3d19e8e056cc0ae0bce1f27a3aa2a7f131a9620ef40c62b3ef9a8903b0';
const DRY_RUN_SHA='f43ee26945eff993000d260823d33d7cf33ac64367b224d05484501db6782ba8';
const SUDOERS_SHA='c343029f9e1faf1eafb70c6a36a0a19620fa8ef7a9c6995f03a5fde2bbf69bb3';
const HELPER_SHA='2bc9fa4261667d5d6660a54b96154629cc3c56a1be6f72085dd390a876bbea8c';
const HELPER_B64='';

const PATHS=Object.freeze({
  base:'/opt/prhm-agent-selfmaint/server.js',
  exec:'/opt/prhm-agent-selfmaint-exec/server.js',
  policy:'/opt/prhm-company-control-plane/config/approval-policy.json',
  mcp:'/home/agent/ssh-mcp-server/src/plugins/hostActionsV2.js',
  helper:'/opt/prhm-agent-selfmaint-exec/actions/honartik-staging-privilege-boundary-install-v1.js'
});
const INSTALL_BACKUP_ROOT='/var/backups/prhm-honartik-staging-privilege-boundary-v28-installer';
const INSTALL_RESULT='/var/lib/prhm-agent-selfmaint-exec/honartik-staging-privilege-boundary-v28-installer/latest.json';

function fail(m){throw new Error(m)}
function sha(v){return crypto.createHash('sha256').update(v).digest('hex')}
function count(s,n){return s.split(n).length-1}
function once(s,a,r,l){if(count(s,a)!==1)fail('anchor_count:'+l+':'+count(s,a));return s.replace(a,r)}
function helperSource(){const s=Buffer.from(HELPER_B64,'base64').toString('utf8');if(sha(s)!==HELPER_SHA)fail('helper_embedded_sha_mismatch');return s}

function buildPolicyCandidate(source){
  const p=JSON.parse(source);
  if(p.schema_version!=='prhm.approval-policy.v1')fail('policy_schema_mismatch');
  if(p.operations&&p.operations[OPERATION])fail('already_present');
  if(Array.isArray(p.typed_scopes)&&p.typed_scopes.some(s=>s&&s.action===ACTION))fail('already_present');
  p.version=POLICY_VERSION;
  p.operations=p.operations||{};
  p.typed_scopes=Array.isArray(p.typed_scopes)?p.typed_scopes:[];
  p.operations[OPERATION]={level:4,risk:'critical',requires_second_confirmation:true,one_time_use:true,requested_approver:'mohammad',expires_seconds:180,policy_version:POLICY_VERSION,rollback_reference:ROLLBACK};
  p.typed_scopes.push({tool:'host_action_v2_apply',project:'control_plane',environment:'production',action:ACTION,risk:'critical',operation:OPERATION,principals:[{principal_id:'mohammad',roles:['mcp-operator']}]});
  return JSON.stringify(p,null,2)+'\n';
}

function buildMcpCandidate(source){
  if(source.includes("'"+ACTION+"'"))fail('already_present');
  const re=/const HostActionV2=z\.enum\(\[([^\n]*?)\]\);/;
  const m=source.match(re);if(!m)fail('mcp_enum_anchor_missing');
  return source.replace(re,"const HostActionV2=z.enum(["+m[1]+",'"+ACTION+"']);");
}

function buildBaseCandidate(source){
  if(source.includes(ACTION))fail('already_present');
  const a="  imotion_credential_bind_v1: { operation: 'host_action.imotion_credential_bind_v1', rollback: 'host-action-v2:imotion-credential-bind-v1:remote-controller-backup-restore' },";
  let out=once(source,a,a+"\n  "+ACTION+": { operation: '"+OPERATION+"', rollback: '"+ROLLBACK+"' },",'base_spec');
  const m=/const HOST_ACTION_V2_LEVEL3 = new Set\((\[[^;]+\])\);/.exec(out);
  if(!m)fail('level3_set_missing');if(m[1].includes(ACTION))fail('action_must_not_be_level3');
  return out;
}

function buildExecCandidate(source){
  if(source.includes(ACTION))fail('already_present');
  const spec="  imotion_credential_bind_v1:{operation:'host_action.imotion_credential_bind_v1',kind:'imotion_credential_bind_v1'},";
  let out=once(source,spec,spec+"\n  "+ACTION+":{operation:'"+OPERATION+"',kind:'"+ACTION+"'},",'exec_spec');
  const fn=[
    "const HONARTIK_STAGING_BOUNDARY_HELPER='/opt/prhm-agent-selfmaint-exec/actions/honartik-staging-privilege-boundary-install-v1.js';",
    "const HONARTIK_STAGING_BOUNDARY_RESULT='/var/lib/prhm-agent-selfmaint-exec/honartik-staging-privilege-boundary-install-v1/latest.json';",
    "function applyHonartikStagingPrivilegeBoundaryInstallV1(){",
    "  const bytes=fs.readFileSync(HONARTIK_STAGING_BOUNDARY_HELPER);",
    "  const actual=require('node:crypto').createHash('sha256').update(bytes).digest('hex');",
    "  if(actual!=='"+HELPER_SHA+"')throw new Error('honartik_staging_boundary_helper_sha_mismatch');",
    "  try{if(fs.existsSync(HONARTIK_STAGING_BOUNDARY_RESULT))fs.unlinkSync(HONARTIK_STAGING_BOUNDARY_RESULT)}catch{}",
    "  const unit='prhm-honartik-staging-boundary-v1-'+Date.now();",
    "  const args=['--wait','--collect','--quiet','--unit='+unit,'--property=Type=oneshot','--property=UMask=0077','--property=NoNewPrivileges=true','--property=PrivateTmp=true','--property=ProtectSystem=strict','--property=ProtectHome=read-only','--property=RestrictAddressFamilies=AF_UNIX','--property=ReadWritePaths=/usr/local/libexec/deploy-control /etc/sudoers.d /var/backups/deploy-control /var/lib/prhm-agent-selfmaint-exec /run','--setenv=PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin','/usr/local/bin/prhm-node',HONARTIK_STAGING_BOUNDARY_HELPER];",
    "  cp.execFileSync('/usr/bin/systemd-run',args,{encoding:'utf8',stdio:['ignore','pipe','pipe'],timeout:180000,maxBuffer:1024*1024});",
    "  if(!fs.existsSync(HONARTIK_STAGING_BOUNDARY_RESULT))throw new Error('honartik_staging_boundary_result_missing');",
    "  const r=readJson(HONARTIK_STAGING_BOUNDARY_RESULT);",
    "  if(!r||r.ok!==true||r.schema_version!=='prhm.host-action-result.v1'||r.action!=='"+ACTION+"'||r.installed!==true||r.dry_run_only!==true||r.direct_apply_sudo_allowed!==false||r.production_application_mutation!==false||r.staging_application_mutation!==false||r.database_mutation!==false||r.rollback_performed!==false)throw new Error('honartik_staging_boundary_result_invalid');",
    "  return r;",
    "}",
    ""
  ].join('\n');
  out=once(out,'const applyHostActionV2Original=applyHostActionV2;',fn+'const applyHostActionV2Original=applyHostActionV2;','exec_helper');
  const apply="if(action==='imotion_credential_bind_v1')return applyImotionCredentialBindV1();";
  out=once(out,apply,apply+"if(action==='"+ACTION+"')return applyHonartikStagingPrivilegeBoundaryInstallV1();",'exec_apply');
  return out;
}

function buildInstallPlan(current){
  for(const k of ['base','exec','policy','mcp'])if(typeof current[k]!=='string')fail('install_source_missing:'+k);
  const expected={base:BASE_SHA,exec:EXEC_SHA,policy:POLICY_SHA,mcp:MCP_SHA};
  for(const k of Object.keys(expected))if(sha(current[k])!==expected[k])fail('install_preimage_sha_mismatch:'+k+':'+sha(current[k]));
  const helper=helperSource();
  const next={base:buildBaseCandidate(current.base),exec:buildExecCandidate(current.exec),policy:buildPolicyCandidate(current.policy),mcp:buildMcpCandidate(current.mcp),helper};
  return {ok:true,action:ACTION,helper_sha256:HELPER_SHA,next,post_sha256:Object.fromEntries(Object.entries(next).map(([k,v])=>[k,sha(v)])),production_application_mutation:false,staging_application_mutation:false,database_mutation:false};
}

function productionDeps(){
  const read=f=>fs.readFileSync(f,'utf8');
  const nodeCheck=(text,label)=>{
    const f='/tmp/prhm-honartik-v28-'+process.pid+'-'+label+'.js';
    try{fs.writeFileSync(f,text,{mode:0o600,flag:'wx'});const r=cp.spawnSync('/usr/local/bin/prhm-node',['--check',f],{encoding:'utf8',timeout:10000});if(r.error||r.status!==0)fail('node_syntax_invalid:'+label)}
    finally{try{fs.unlinkSync(f)}catch{}}
  };
  const atomic=(file,text,mode)=>{
    const tmp=file+'.honartik-v28-'+process.pid+'-'+Date.now()+'.tmp',prior=fs.existsSync(file)?fs.statSync(file):null;let fd;
    try{fd=fs.openSync(tmp,'wx',mode);fs.writeFileSync(fd,text);fs.fsyncSync(fd);fs.closeSync(fd);fd=undefined;fs.chmodSync(tmp,mode);if(prior)fs.chownSync(tmp,prior.uid,prior.gid);fs.renameSync(tmp,file)}
    catch(e){try{if(fd!==undefined)fs.closeSync(fd)}catch{}try{fs.unlinkSync(tmp)}catch{}throw e}
  };
  const restart=service=>{const r=cp.spawnSync('/usr/bin/systemctl',['restart',service],{encoding:'utf8',timeout:60000});if(r.error||r.status!==0)fail('service_restart_failed:'+service)};
  const active=service=>String(cp.spawnSync('/usr/bin/systemctl',['is-active',service],{encoding:'utf8',timeout:10000}).stdout||'').trim()==='active';
  return {fs,path,read,nodeCheck,atomic,restart,active};
}

function preflight(deps=productionDeps()){
  const current={base:deps.read(PATHS.base),exec:deps.read(PATHS.exec),policy:deps.read(PATHS.policy),mcp:deps.read(PATHS.mcp)};
  const plan=buildInstallPlan(current);
  deps.nodeCheck(plan.next.base,'base');deps.nodeCheck(plan.next.exec,'exec');deps.nodeCheck(plan.next.mcp,'mcp');deps.nodeCheck(plan.next.helper,'helper');JSON.parse(plan.next.policy);
  return {ok:true,schema_version:'prhm.honartik-staging-privilege-boundary-installer-preflight.v1',action:ACTION,preflight_only:true,helper_sha256:HELPER_SHA,post_sha256:plan.post_sha256,production_application_mutation:false,staging_application_mutation:false,database_mutation:false,policy_mutation:true,control_plane_mutation:true};
}

function install(deps=productionDeps()){
  if(process.getuid&&process.getuid()!==0)fail('root_required');
  const pf=preflight(deps),current={base:deps.read(PATHS.base),exec:deps.read(PATHS.exec),policy:deps.read(PATHS.policy),mcp:deps.read(PATHS.mcp)},plan=buildInstallPlan(current);
  const stamp=new Date().toISOString().replace(/[-:.TZ]/g,'').slice(0,14),backup=path.join(INSTALL_BACKUP_ROOT,stamp+'-'+process.pid);
  deps.fs.mkdirSync(backup,{recursive:true,mode:0o700});
  const modes={};for(const k of ['base','exec','policy','mcp']){modes[k]=deps.fs.statSync(PATHS[k]).mode&0o777;deps.fs.writeFileSync(path.join(backup,k+'.bak'),current[k],{mode:0o600,flag:'wx'})}
  const helperExisted=deps.fs.existsSync(PATHS.helper),helperOld=helperExisted?deps.fs.readFileSync(PATHS.helper):null;if(helperExisted)deps.fs.writeFileSync(path.join(backup,'helper.bak'),helperOld,{mode:0o600,flag:'wx'});
  const services=['prhm-company-approval.service','prhm-agent-selfmaint.service','prhm-agent-selfmaint-exec.service','prhm-agent-mcp.service'];let mutated=false;
  try{
    deps.atomic(PATHS.helper,plan.next.helper,0o700);for(const k of ['base','exec','policy','mcp'])deps.atomic(PATHS[k],plan.next[k],modes[k]);mutated=true;
    for(const s of services)deps.restart(s);for(const s of services)if(!deps.active(s))fail('service_not_active:'+s);
    for(const k of ['base','exec','policy','mcp'])if(sha(deps.read(PATHS[k]))!==plan.post_sha256[k])fail('post_install_sha_mismatch:'+k);
    if(sha(deps.fs.readFileSync(PATHS.helper))!==HELPER_SHA)fail('post_install_sha_mismatch:helper');
    return {ok:true,schema_version:'prhm.honartik-staging-privilege-boundary-installer-result.v1',action:ACTION,installed:true,backup_dir:backup,helper_sha256:HELPER_SHA,post_sha256:plan.post_sha256,production_application_mutation:false,staging_application_mutation:false,database_mutation:false,rollback_performed:false,preflight:pf};
  }catch(error){
    const rb=[];if(mutated){for(const k of ['base','exec','policy','mcp'])try{deps.atomic(PATHS[k],current[k],modes[k])}catch(e){rb.push(k+':'+e.message)}try{if(helperExisted)deps.atomic(PATHS.helper,helperOld,0o700);else deps.fs.unlinkSync(PATHS.helper)}catch(e){rb.push('helper:'+e.message)}for(const s of services)try{deps.restart(s)}catch(e){rb.push('restart:'+s+':'+e.message)}}
    if(rb.length)fail('install_failed_rollback_failed:'+String(error&&error.message||error)+':'+rb.join('|'));fail('install_failed_rolled_back:'+String(error&&error.message||error));
  }
}

function selftest(){
  const policy=JSON.stringify({schema_version:'prhm.approval-policy.v1',version:'x',operations:{},typed_scopes:[]});
  const base="const HOST_ACTION_V2_SPECS = Object.freeze({\\n  imotion_credential_bind_v1: { operation: 'host_action.imotion_credential_bind_v1', rollback: 'host-action-v2:imotion-credential-bind-v1:remote-controller-backup-restore' },\\n});\\nconst HOST_ACTION_V2_LEVEL3 = new Set([\\\"control_plane_root_scripts_stage_transport_v1\\\"]);";
  const exec="const HOST_ACTION_V2_SPECS = Object.freeze({\\n  imotion_credential_bind_v1:{operation:'host_action.imotion_credential_bind_v1',kind:'imotion_credential_bind_v1'},\\n});\\nconst applyHostActionV2Original=applyHostActionV2;\\napplyHostActionV2=async function(action){if(action==='imotion_credential_bind_v1')return applyImotionCredentialBindV1();return applyHostActionV2Original(action);};";
  const mcp="const HostActionV2=z.enum(['control_plane_root_scripts_stage_transport_v1']);";
  const out={policy:buildPolicyCandidate(policy),base:buildBaseCandidate(base),exec:buildExecCandidate(exec),mcp:buildMcpCandidate(mcp)};
  const p=JSON.parse(out.policy);if(Number(p.operations[OPERATION].level)!==4)fail('selftest_level');if(!out.exec.includes('applyHonartikStagingPrivilegeBoundaryInstallV1'))fail('selftest_exec');if(!out.mcp.includes(ACTION))fail('selftest_mcp');if(!helperSource().includes('direct_apply_sudo_allowed:false'))fail('selftest_helper');
  return {ok:true,action:ACTION,helper_sha256:HELPER_SHA};
}

function main(){
  const args=process.argv.slice(2);if(args.length>1)fail('unexpected_arguments');
  if(args[0]==='--selftest-only'){process.stdout.write(JSON.stringify(selftest())+'\n');return}
  if(args[0]==='--preflight-only'){process.stdout.write(JSON.stringify(preflight())+'\n');return}
  if(args.length!==0)fail('unexpected_argument:'+args[0]);
  const result=install();fs.mkdirSync(path.dirname(INSTALL_RESULT),{recursive:true,mode:0o700});const tmp=INSTALL_RESULT+'.'+process.pid+'.tmp';fs.writeFileSync(tmp,JSON.stringify(result,null,2)+'\n',{mode:0o600,flag:'wx'});fs.renameSync(tmp,INSTALL_RESULT);process.stdout.write(JSON.stringify(result)+'\n');
}

module.exports={ACTION,OPERATION,POLICY_VERSION,ROLLBACK,BASE_SHA,EXEC_SHA,POLICY_SHA,MCP_SHA,DRIVER_SHA,DRY_RUN_SHA,SUDOERS_SHA,HELPER_SHA,PATHS,helperSource,buildPolicyCandidate,buildMcpCandidate,buildBaseCandidate,buildExecCandidate,buildInstallPlan,productionDeps,preflight,install,selftest,sha};
if(require.main===module){try{main()}catch(error){console.error(String(error&&error.stack||error));process.exit(1)}}
